INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Betroffenenrechte > Recht auf Einschränkung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gewährt Art. 18 DSGVO Betroffenen das Recht, die Einschränkung der Verarbeitung ihrer personenbezogenen Daten zu verlangen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 18 DSGVO garantiert das Recht auf Einschränkung"}, {"text": "Nein", "correct": false, "because": "Recht ist gesetzlich verankert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Recht auf Einschränkung ausgeübt werden, wenn die Richtigkeit der Daten vom Betroffenen bestritten wird?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 18 Abs. 1a DSGVO nennt dies als Grund"}, {"text": "Nein", "correct": false, "because": "Richtigkeit ein Einschränkungsgrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Unternehmen die Verarbeitung immer einschränken, auch wenn gesetzliche Verpflichtungen dagegenstehen?', 2, '[{"text": "Nein", "correct": true, "because": "Gesetzliche Pflichten können Vorrang haben"}, {"text": "Ja", "correct": false, "because": "Ausnahmen sind vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Betroffene das Recht auf Einschränkung nutzen, wenn die Verarbeitung unrechtmäßig ist, sie aber nicht die Löschung wünschen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 18 Abs. 1c DSGVO erlaubt dies"}, {"text": "Nein", "correct": false, "because": "Unrechtmäßigkeit ein Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Recht auf Einschränkung gemäß Art. 18 DSGVO kostenpflichtig für Betroffene?', 2, '[{"text": "Nein", "correct": true, "because": "Art. 12 Abs. 5 DSGVO schreibt Kostenfreiheit vor"}, {"text": "Ja", "correct": false, "because": "Kostenfreiheit ist Standard"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was erlaubt das Recht auf Einschränkung gemäß Art. 18 DSGVO Betroffenen?', 2, '[{"text": "Beschränkung der Verarbeitung ihrer Daten", "correct": true, "because": "Art. 18 DSGVO definiert dies"}, {"text": "Maximale Datenerhebung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grund berechtigt Betroffene zur Ausübung des Rechts auf Einschränkung?', 3, '[{"text": "Richtigkeit der Daten wird bestritten", "correct": true, "because": "Art. 18 Abs. 1a DSGVO nennt dies"}, {"text": "Daten sind öffentlich", "correct": false, "because": "Kein Einschränkungsgrund"}, {"text": "Daten sind noch zweckmäßig", "correct": false, "because": "Kein Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frist haben Unternehmen, um ein Einschränkungsverlangen nach Art. 18 DSGVO zu bearbeiten?', 2, '[{"text": "Einen Monat", "correct": true, "because": "Art. 12 Abs. 3 DSGVO setzt eine Monatsfrist"}, {"text": "Drei Monate", "correct": false, "because": "Zu lang"}, {"text": "Keine Frist", "correct": false, "because": "Frist ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme müssen Unternehmen bei einem Einschränkungsverlangen ergreifen?', 2, '[{"text": "Verarbeitung einschränken oder Einschränkung begründen", "correct": true, "because": "Pflicht nach Art. 18 DSGVO"}, {"text": "Daten löschen", "correct": false, "because": "Anderes Recht"}, {"text": "Daten ignorieren", "correct": false, "because": "Verstoß gegen DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grundsatz nach Art. 5 DSGVO wird durch das Recht auf Einschränkung unterstützt?', 2, '[{"text": "Richtigkeit", "correct": true, "because": "Einschränkung bei bestrittener Richtigkeit"}, {"text": "Zweckbindung", "correct": false, "because": "Anderer Fokus"}, {"text": "Datenminimierung", "correct": false, "because": "Anderer Aspekt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Gründe berechtigen Betroffene zur Ausübung des Rechts auf Einschränkung nach Art. 18 DSGVO?', 4, '[{"text": "Richtigkeit der Daten wird bestritten", "correct": true, "because": "Art. 18 Abs. 1a"}, {"text": "Verarbeitung ist unrechtmäßig", "correct": true, "because": "Art. 18 Abs. 1c"}, {"text": "Daten nicht mehr für Zweck nötig", "correct": true, "because": "Art. 18 Abs. 1b"}, {"text": "Daten sind öffentlich", "correct": false, "because": "Kein Einschränkungsgrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Unternehmen bei einem Einschränkungsverlangen?', 3, '[{"text": "Verarbeitung innerhalb eines Monats einschränken", "correct": true, "because": "Frist nach Art. 12"}, {"text": "Betroffene über Einschränkung informieren", "correct": true, "because": "Pflicht nach Art. 18 Abs. 3"}, {"text": "Kostenfrei handeln", "correct": true, "because": "Art. 12 Abs. 5"}, {"text": "Daten löschen", "correct": false, "because": "Anderes Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen die Umsetzung des Rechts auf Einschränkung?', 4, '[{"text": "Daten markieren", "correct": true, "because": "Einschränkung sichtbar machen"}, {"text": "Verarbeitung pausieren", "correct": true, "because": "Einschränkung umsetzen"}, {"text": "Betroffenenrechte dokumentieren", "correct": true, "because": "Nachweisbarkeit"}, {"text": "Daten weiterverarbeiten", "correct": false, "because": "Verstoß gegen Einschränkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ausnahmen können die Einschränkung der Verarbeitung verhindern?', 3, '[{"text": "Gesetzliche Verpflichtungen", "correct": true, "because": "Vorrang vor Einschränkung"}, {"text": "Schutz der Rechte anderer", "correct": true, "because": "Art. 18 Abs. 2"}, {"text": "Öffentliches Interesse", "correct": true, "because": "Art. 18 Abs. 2"}, {"text": "Unternehmensinteresse", "correct": false, "because": "Kein allgemeiner Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen das Recht auf Einschränkung haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen DSGVO strafbar"}, {"text": "Schadensersatz", "correct": true, "because": "Betroffene können klagen"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kundenvertrauen schwindet"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Recht auf Einschränkung gilt bei bestrittener Datenrichtigkeit. b) Es ist kostenpflichtig für Betroffene.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Richtigkeit ja, kostenfrei nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unternehmen müssen die Verarbeitung bei unrechtmäßiger Nutzung einschränken. b) Gesetzliche Pflichten können die Einschränkung verhindern.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Unrechtmäßigkeit ja, Pflichten Ausnahme"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verstöße gegen das Recht auf Einschränkung können Bußgelder nach sich ziehen. b) Die Einschränkung gilt nur bei digitalen Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, alle Daten betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Bearbeitung eines Einschränkungsverlangens dauert einen Monat. b) Unternehmen müssen die Verarbeitung immer einschränken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Frist ja, Ausnahmen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Recht auf Einschränkung unterstützt den Grundsatz der Richtigkeit. b) Es erfordert keine Dokumentation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Richtigkeit ja, Dokumentation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

